/* Conjunto ativo agora (3D ou simples), decidido numa checagem só —
   quem usa os ícones novos (getIconeSVG/getIconeFragmento) nunca faz
   essa checagem sozinho, só chama uma dessas duas funções. */
function conjuntoDeIconesAtivo() {
  return estiloPlanetasEsferico() ? ICONES_3D : ICONES_SIMPLES_NOVO;
}

/* Os ícones novos vêm do SVGOMG com IDs de gradiente/clipPath curtos e
   genéricos (id="a", id="b"...) — ótimo pra um ícone sozinho, mas quando
   dois ou mais aparecem juntos na MESMA página (ex.: os 7 planetas na
   roda da mandala), o navegador trata todo id="x" da página como um
   espaço só: o segundo "a" rouba a definição do primeiro, e as cores
   saem erradas ou o ícone some (mesmo bug que já existe resolvido em
   sinastria.js/profeccao.js/liberacao.js pros ícones antigos, com o
   sufixo `_${sufixo}` manual). Aqui a correção é automática: cada
   chamada recebe um sufixo novo, sempre. */
let _iconeSufixoContador = 0;
function _namespacearIdsIcone(svgTexto) {
  const sufixo = 'ic' + (_iconeSufixoContador++);
  return svgTexto
    .replace(/\bid="([^"]+)"/g, (m, id) => `id="${id}_${sufixo}"`)
    .replace(/url\(#([^)]+)\)/g, (m, id) => `url(#${id}_${sufixo})`);
}

/* ÍCONES DE PAPIRO (só no Tema Céu, fora da roda da Mandala) — os mesmos desenhos dos ícones
   "simples", mas em TINTA chapada em vez do dourado com gradiente: azul-tinta (#1d3a66) e, nos
   planetas que estão na SEITA do mapa, terracota (#a03e25). A seita (hairesis) é helenística:
   mapa diurno -> Sol, Júpiter e Saturno; mapa noturno -> Lua, Vênus e Marte; Mercúrio é diurno
   quando oriental (nasce antes do Sol) e noturno quando ocidental. A roda da Mandala tem estilo
   próprio no Tema Céu (pontos de luz) e não passa por aqui. Fora do Tema Céu nada muda. */
const COR_TINTA_AZUL = '#1d3a66';
const COR_TINTA_TERRACOTA = '#a03e25';

function temaCeuAtivoNosIcones() {
  return typeof window !== 'undefined' && window.temaMandala === 'ceu';
}

/* Seita do mapa aberto, a partir de currentCalculatedData (posições em graus absolutos).
   Devolve { diurno, mercurioOriental } ou null se não houver mapa carregado. */
function seitaDoMapaAtual(dados) {
  // 'dados' (opcional): a seita de OUTRO mapa (ex.: a Revolução Solar desenhada numa roda secundária); sem ele, o mapa aberto.
  const d = dados || ((typeof currentCalculatedData !== 'undefined') ? currentCalculatedData : null);
  if (!d || !d.Ascendente || !d['Sol']) return null;
  const sol = d['Sol'].grau_absoluto, asc = d.Ascendente.grau_absoluto;
  if (typeof sol !== 'number' || typeof asc !== 'number') return null;
  const diurno = ((sol - asc + 360) % 360) >= 180;
  const merc = d['Mercúrio'] && d['Mercúrio'].grau_absoluto;
  const mercurioOriental = (typeof merc === 'number') ? (((sol - merc + 360) % 360) < 180) : true;
  return { diurno, mercurioOriental };
}

function planetaEstaNaSeita(planetId, dados) {
  const s = seitaDoMapaAtual(dados);
  if (!s) return false;
  if (planetId === 'Mercury') return s.diurno ? s.mercurioOriental : !s.mercurioOriental;
  return s.diurno ? ['Sun', 'Jupiter', 'Saturn'].includes(planetId) : ['Moon', 'Venus', 'Mars'].includes(planetId);
}

function corIconePapiro(categoria, chave, dados) {
  return (categoria === 'planeta' && planetaEstaNaSeita(chave, dados)) ? COR_TINTA_TERRACOTA : COR_TINTA_AZUL;
}

/* Recolore o SVG de um ícone simples pra tinta chapada: tira o <defs> (gradientes), pinta cada
   forma com a cor, e um traço fininho da mesma cor arredonda as pontas. */
function recolorirIconePapiro(bruto, cor) {
  const abre = bruto.indexOf('>') + 1;
  const fecha = bruto.lastIndexOf('</svg>');
  let miolo = bruto.slice(abre, fecha).replace(/<defs>[\s\S]*?<\/defs>/g, '');
  miolo = miolo.replace(/<g([^>]*)>/g, (x, a) => `<g${a.replace(/\s(fill|clip-path)="[^"]*"/g, '')}>`);
  miolo = miolo.replace(/<(path|circle)\b([^>]*?)(\/?)>/g, (x, tag, a, fim) => {
    const comContorno = /stroke="/.test(a);
    a = a.replace(/\s(fill|stroke)="[^"]*"/g, '');
    const sw = (a.match(/stroke-width="([^"]+)"/) || [0, 3])[1];
    a = a.replace(/\sstroke-width="[^"]*"/g, '');
    return comContorno
      ? `<${tag}${a} fill="none" stroke="${cor}" stroke-width="${sw}" stroke-linejoin="round"${fim}>`
      : `<${tag}${a} fill="${cor}" stroke="${cor}" stroke-width=".9" stroke-linejoin="round"${fim}>`;
  });
  return bruto.slice(0, abre) + miolo + '</svg>';
}

/* SVG bruto do ícone: o de sempre, ou o de papiro no Tema Céu. */
function brutoDoIcone(categoria, chave, dados) {
  if (temaCeuAtivoNosIcones()) {
    const base = (ICONES_SIMPLES_NOVO[categoria] || {})[chave] || '';
    return base ? recolorirIconePapiro(base, corIconePapiro(categoria, chave, dados)) : '';
  }
  return (conjuntoDeIconesAtivo()[categoria] || {})[chave] || '';
}

/* Ícone novo pronto pra usar (tag <svg> completa), no tamanho pedido.
   categoria: 'planeta' | 'lote' | 'outro'. chave: ex. "Sun", "fortune",
   "sizigia", "northNode", "southNode", "angulo". */
function getIconeSVG(categoria, chave, tamanho = 34, dados) {
  const bruto = brutoDoIcone(categoria, chave, dados);
  if (!bruto) return '';
  return _namespacearIdsIcone(bruto.replace('<svg ', `<svg width="${tamanho}" height="${tamanho}" `));
}

/* Mesmo ícone novo, como miolo pronto pra embutir dentro de um <svg> já
   existente (ex.: a roda da mandala) — sem a tag <svg> externa, só o
   conteúdo (formas + defs) dentro de um <g>, pra quem usa escalar/girar
   como quiser por fora. */
function getIconeFragmento(categoria, chave, dados) {
  const bruto = brutoDoIcone(categoria, chave, dados);
  if (!bruto) return '';
  const abre = bruto.indexOf('>') + 1;
  const fecha = bruto.lastIndexOf('</svg>');
  /* O <svg fill="none"> original dá um preenchimento padrão "nenhum" pra
     tudo que está dentro e não declara fill próprio (ex.: o anel só de
     contorno da Necessidade/Eros). Sem essa tag, esse "nenhum" some, e
     o SVG cai no padrão dele mesmo (preto sólido) pra essas formas —
     por isso o <g> aqui precisa repetir fill="none". */
  return _namespacearIdsIcone(`<g fill="none">${bruto.slice(abre, fecha)}</g>`);
}

/* Uma "mancha" só de cor, com a mesma silhueta do ícone (pega o "d" de
   cada <path> do ícone e preenche tudo com corFundo, ignorando a cor
   original) — pra desenhar atrás de um ícone que não é redondo (ex.:
   o triângulo do ângulo), em vez de usar um círculo genérico que sobra
   pra fora e cobre coisa que não devia. */
function getIconeFundoSilhueta(categoria, chave, corFundo) {
  const bruto = (conjuntoDeIconesAtivo()[categoria] || {})[chave] || '';
  if (!bruto) return '';
  const abre = bruto.indexOf('>') + 1;
  const fecha = bruto.lastIndexOf('</svg>');
  const miolo = bruto.slice(abre, fecha);
  /* Tira o <defs>...</defs> antes de procurar <path> — lá dentro tem o
     retângulo do clipPath (cobre o quadrado 100x100 inteiro) e paths de
     gradiente, que não são a silhueta visível do ícone. */
  const semDefs = miolo.replace(/<defs>[\s\S]*?<\/defs>/, '');
  const ds = [...semDefs.matchAll(/<path[^>]*\sd="([^"]+)"/g)].map(m => m[1]);
  if (ds.length === 0) return '';
  const paths = ds.map(d => `<path d="${d}" fill="${corFundo}"/>`).join('');
  return `<g>${paths}</g>`;
}

/* Ícone fixo de termo/circunambulação, no tamanho pedido. planetId:
   "Mercury" | "Venus" | "Mars" | "Jupiter" | "Saturn". Os traços desse
   ícone são desenhados com fill="currentColor" (sem cor própria de
   propósito) pra sempre acompanhar o dourado de quem chama — passa a
   cor de dourado certa (que muda com o tema) em `cor`. */
function getIconeTermoSVG(planetId, tamanho = 18, cor = '#c59b27') {
  const bruto = ICONES_TERMOS[planetId] || '';
  if (!bruto) return '';
  const comTamanho = bruto.replace('<svg ', `<svg width="${tamanho}" height="${tamanho}" style="color: ${cor};" `);
  return _namespacearIdsIcone(comTamanho);
}
